**Gates before launch.** I run four gates, and if any of them fails I stop and report instead of launching. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are in the "SPE r04 predict" commit and have not changed since. Second, I run `python spe/evals/graders/grade.py --selftest`. The oracle built from spe/evals/tasks/answers.json must score 100 percent on label.category and label.priority, and both an empty output and a shuffled-label output must fail. In the same gate I check that answers.json has exactly 50 ticket ids and that the label-free copies in /tmp/spe-triage/tickets/ match those ids. Third, I regrade round 3's saved outputs with this grade.py as a control. The numbers must match what spe/prediction-log.md recorded for round 3. If they differ, the grader changed, and I log that in spe/failures.md before going on. Fourth, I do a dry run with `args.only = ["B:T007", "C2:T031"]` and `args.trials = 2`. I check that every trial, grade, audit, and judge result fits its schema. I also confirm that the cost measured per trial (which replaces `estTrialUsd` and `judgeCallUsd`) keeps the projected total under $40. Then I commit the script as spe/evals/harness/r04-workflow.js with the message "SPE r04 evaluate (harness)" and launch it.

**Defaults I chose.** The project describes 40 historical tickets, but the approved plan says 50. The script follows the plan: it uses ticket ids T001 to T050 and refuses to run unless it gets exactly 50. The launcher stages label-free ticket copies at /tmp/spe-triage/tickets/<id>.json, so trials never need to read spe/evals/. The approved plan did not mention top-up trials, so their results are reported separately. The primary numbers that get scored against r04.yaml come only from the 5 planned trials per cell.

```js
export const meta = {
  name: "spe-triage-eval",
  description: "SPE eval for the triage agent. Runs each config on each ticket, grades label.category and label.priority with grade.py, judges reply tone blind with an Opus judge, tops up split cells under a cap, then runs failure analysis and a completeness critic.",
  phases: ["Trials", "Audit", "Grade", "Top-up", "Judge", "Synthesis"],
};

// The round is set here only. Labels, paths, and prompts derive from it.
const ROUND = Number(args.round ?? 4);
const R = `r${String(ROUND).padStart(2, "0")}`;

// Configs from the approved plan. C2 changes one thing from B: the tool set.
const CONFIGS = {
  B: "Sonnet 5.5, 12-line prompt, 6 tools",
  C2: "Sonnet 5.5, 12-line prompt, 3 merged tools plus a separate check_status tool",
};
const CONFIG_IDS = args.configs ?? Object.keys(CONFIGS);

const EXPECTED_TICKETS = args.expectedTickets ?? 50;
const TICKETS = args.tickets ?? Array.from({ length: EXPECTED_TICKETS }, (_, i) => `T${String(i + 1).padStart(3, "0")}`);
const TRIALS = args.trials ?? 5;
const ONLY = args.only ?? null; // dry run, for example ["B:T007", "C2:T031"]

// Budget. One cap covers all paid spend in this run.
const CAP_USD = args.capUsd ?? 40;
const EST_TRIAL_USD = args.estTrialUsd ?? 0.04;   // unmeasured default, replaced from the dry run
const JUDGE_CALL_USD = args.judgeCallUsd ?? 0.15; // unmeasured default, replaced from the dry run

const TOPUP_PER_CELL = args.topupPerCell ?? 3;
const TOPUP_MAX_CELLS = args.topupMaxCells ?? 20;
const WAVE = args.wave ?? 10;
const MAX_VOID_FRAC = args.maxVoidFrac ?? 0.02;

const RUN_DIR = args.runDir ?? `/tmp/spe-triage/${R}`;
const TICKET_DIR = args.ticketDir ?? "/tmp/spe-triage/tickets";
const AGENT_DIR = args.agentDir ?? "triage/";
const TRANSCRIPT_DIR = args.transcriptDir ?? null;
const RUN_CMD = args.runCmd ?? "python -m triage.run --config {config} --ticket {ticket} --trace {trace} --json";
const SELFTEST_CMD = args.selftestCmd ?? "python spe/evals/graders/grade.py --selftest";
const GRADE_CMD = args.gradeCmd ?? "python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --input {input} --json";
const JUDGE_RUBRIC = "spe/evals/graders/judge.md";
const AGENT_MODEL = args.agentModel ?? "opus";
const JUDGE_MODEL = "opus";

// Any of these strings in a trial's reads means the trial peeked.
const FORBIDDEN = ["spe/evals/", "spe/predictions/", "spe/plans/", "spe/prediction-log", "answers.json", "grade.py", "judge.md"];

// ---------- helpers ----------
const sum = (xs) => xs.reduce((a, b) => a + (Number(b) || 0), 0);
const mean = (xs) => (xs.length ? sum(xs) / xs.length : null);
const rate = (xs, f) => (xs.length ? xs.filter(f).length / xs.length : null);
const r3 = (x) => (x == null ? null : Math.round(x * 1000) / 1000);
const range = (a, b) => Array.from({ length: Math.max(0, b - a + 1) }, (_, i) => a + i);
const key = (c, t, n) => `${c}:${t}:${n}`;
const fill = (tpl, vals) => tpl.replace(/\{(\w+)\}/g, (_, k) => vals[k]);
const groupBy = (xs, f) => xs.reduce((m, x) => ((m[f(x)] ??= []).push(x), m), {});
function seeded(str) {
  let h = 2166136261;
  for (const ch of str) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  if (h === 0) h = 1;
  return () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; return ((h >>> 0) % 1000000) / 1000000; };
}
async function inWaves(items, fn) {
  for (let i = 0; i < items.length; i += WAVE) {
    await parallel(items.slice(i, i + WAVE).map((x) => () => fn(x)));
    log(`${Math.min(i + WAVE, items.length)}/${items.length} done, spend ~$${spentUsd.toFixed(2)} of $${CAP_USD}`);
  }
}

// ---------- state ----------
const records = new Map();
const all = () => [...records.values()];
const voids = [];
const skipped = [];
const auditNotes = [];
const gradeNotes = [];
const judgeNotes = [];
let spentUsd = 0;

function reserve(usd, what) {
  if (spentUsd + usd > CAP_USD) {
    skipped.push({ what, need_usd: r3(usd), spent_usd: r3(spentUsd) });
    log(`SKIP ${what}: would cross the $${CAP_USD} cap (spent ~$${spentUsd.toFixed(2)}, needs ~$${usd.toFixed(2)})`);
    return false;
  }
  spentUsd += usd;
  return true;
}
function voidRecord(r, evidence) {
  if (r.void) return;
  r.void = evidence;
  voids.push({ config: r.config, ticket: r.ticket, trial: r.trial, evidence });
}

// ---------- schemas ----------
const RUN_ITEM = {
  type: "object",
  required: ["trial", "status"],
  properties: {
    trial: { type: "integer" },
    status: { type: "string", enum: ["completed", "harness_error", "rate_limited"] },
    category: { type: "string" },
    priority: { type: "string" },
    reply: { type: "string" },
    runtime_ms: { type: "number" },
    tool_calls: { type: "integer" },
    tool_errors: { type: "integer" },
    input_tokens: { type: "integer" },
    output_tokens: { type: "integer" },
    cost_usd: { type: "number" },
    trace_path: { type: "string" },
    error: { type: "string" },
  },
};
const TRIAL_SCHEMA = {
  type: "object",
  required: ["config", "ticket", "runs", "paths_opened"],
  properties: {
    config: { type: "string" },
    ticket: { type: "string" },
    runs: { type: "array", items: RUN_ITEM },
    paths_opened: { type: "array", items: { type: "string" } },
  },
};
const AUDIT_SCHEMA = {
  type: "object",
  required: ["voided", "missing_traces", "traces_scanned", "transcripts_scanned"],
  properties: {
    voided: { type: "array", items: { type: "object", required: ["ticket", "trial", "evidence"], properties: { ticket: { type: "string" }, trial: { type: "integer" }, evidence: { type: "string" } } } },
    missing_traces: { type: "array", items: { type: "string" } },
    traces_scanned: { type: "integer" },
    transcripts_scanned: { type: "integer" },
    notes: { type: "string" },
  },
};
const GRADE_SCHEMA = {
  type: "object",
  required: ["selftest_passed", "results"],
  properties: {
    selftest_passed: { type: "boolean" },
    selftest_output: { type: "string" },
    results: { type: "array", items: { type: "object", required: ["ticket", "trial", "category_ok", "priority_ok"], properties: {
      ticket: { type: "string" }, trial: { type: "integer" },
      category_ok: { type: "boolean" }, priority_ok: { type: "boolean" },
      expected_category: { type: "string" }, expected_priority: { type: "string" },
    } } },
    errors: { type: "array", items: { type: "string" } },
  },
};
const JUDGE_SCHEMA = {
  type: "object",
  required: ["scores"],
  properties: {
    scores: { type: "array", items: { type: "object", required: ["reply_id", "tone", "pass"], properties: {
      reply_id: { type: "string" }, tone: { type: "number" }, pass: { type: "boolean" }, note: { type: "string" },
    } } },
  },
};
const FAILURE_SCHEMA = {
  type: "object",
  required: ["failure_types"],
  properties: {
    failure_types: { type: "array", items: { type: "object", required: ["name", "kind", "count", "what", "how_to_spot", "proposed_fix"], properties: {
      name: { type: "string" }, kind: { type: "string" }, existing_id: { type: "string" },
      configs: { type: "array", items: { type: "string" } }, tickets: { type: "array", items: { type: "string" } },
      count: { type: "integer" }, what: { type: "string" }, how_to_spot: { type: "string" }, proposed_fix: { type: "string" },
    } } },
    proposals_next_round: { type: "array", items: { type: "string" } },
  },
};
const CRITIC_SCHEMA = {
  type: "object",
  required: ["complete", "gaps"],
  properties: { complete: { type: "boolean" }, gaps: { type: "array", items: { type: "string" } } },
};

// ---------- prompts ----------
function trialPrompt(cell, nums) {
  const cmds = nums.map((n) => `  trial ${n}: ` + fill(RUN_CMD, {
    config: cell.config,
    ticket: `${TICKET_DIR}/${cell.ticket}.json`,
    trace: `${RUN_DIR}/${cell.config}/${cell.ticket}/t${n}.trace.jsonl`,
  })).join("\n");
  return [
    "You are a harness runner for the triage agent. You run commands and copy their output. You do not judge, fix, or improve anything.",
    `Config: ${cell.config} (${CONFIGS[cell.config]}). Ticket: ${cell.ticket}.`,
    `You may read only ${TICKET_DIR}/${cell.ticket}.json and files under ${AGENT_DIR}. Do not open, list, grep, or search anything under spe/. Do not look for reference labels anywhere.`,
    `Create ${RUN_DIR}/${cell.config}/${cell.ticket}/ if it does not exist. Then run each command once, in order:`,
    cmds,
    "Each command prints one JSON object. Copy label.category, label.priority, reply, runtime_ms, tool_calls, tool_errors, input_tokens, output_tokens, and cost_usd from it unchanged. Set trace_path to the --trace path.",
    "Do not re-run a trial because its label looks wrong. If a command fails before the model is called, retry it once. If it still fails or hits a rate limit, set status to harness_error or rate_limited, put the error text in error, and go on.",
    "List every file path you opened or listed in paths_opened.",
  ].join("\n\n");
}

function auditPrompt(cfg, recs, ph) {
  const traces = recs.filter((r) => r.trace_path).map((r) => `${r.ticket} t${r.trial}: ${r.trace_path}`).join("\n");
  return [
    "You audit trial runs for reads of hidden files. You report what you find and change nothing.",
    `Config ${cfg}. Search each trace file below for any of these strings: ${FORBIDDEN.join(", ")}. A match inside a tool call, file read, or shell command counts. Report each match as a void with the ticket, the trial, and the matching line as evidence.`,
    traces || "(no traces)",
    TRANSCRIPT_DIR
      ? `Also search the agent transcripts under ${TRANSCRIPT_DIR} whose label starts with "${R} ${ph} ${cfg} " for the same strings. Report matches the same way.`
      : "No transcript directory was given. Scan the traces only and say so in notes.",
    "List any trace path that does not exist in missing_traces.",
  ].join("\n\n");
}

function gradePrompt(input, payload) {
  return [
    "You run the code grader. You do not grade by judgment. You do not edit the grader, the answers file, or the records.",
    `1. Run: ${SELFTEST_CMD}\nSet selftest_passed to true only if it exits 0 and reports that the oracle passes and the empty and wrong answers fail. Put its last lines in selftest_output. If it fails, stop and return an empty results array.`,
    `2. Write this JSON array to ${input} exactly as given:\n${payload}`,
    `3. Run: ${fill(GRADE_CMD, { input })}`,
    "4. For each record, copy category_ok and priority_ok from the grader output. Add expected_category and expected_priority if the grader prints them. Put any grader warnings in errors.",
  ].join("\n\n");
}

function judgePrompt(ticket, items) {
  return [
    `You judge the tone of first replies to a support ticket. Read the rubric at ${JUDGE_RUBRIC} and the ticket at ${TICKET_DIR}/${ticket}.json.`,
    "Score each reply on that rubric only. Do not score the category or the priority. The replies come from different systems in random order. You are not told which system wrote which reply, so do not guess.",
    "Return one score per reply_id. Use the rubric's scale for tone, set pass as the rubric defines it, and add a one-sentence note.",
    ...items.map((x) => `--- ${x.id} ---\n${x.r.reply}`),
  ].join("\n\n");
}

// ---------- stages ----------
async function runCell(cell, ph) {
  const est = EST_TRIAL_USD * cell.nums.length;
  if (!reserve(est, `${ph} ${cell.config}:${cell.ticket} trials ${cell.nums.join(",")}`)) return;
  let out;
  try {
    out = await agent(trialPrompt(cell, cell.nums), { label: `${R} ${ph} ${cell.config} ${cell.ticket}`, phase: ph, schema: TRIAL_SCHEMA, model: AGENT_MODEL });
  } catch (e) {
    // The spend is unknown here, so the reservation stays.
    out = { config: cell.config, ticket: cell.ticket, paths_opened: [], runs: [], error: String(e) };
  }
  const runs = (out.runs || []).filter((r) => cell.nums.includes(r.trial));
  if (runs.length) spentUsd += sum(runs.map((r) => r.cost_usd ?? EST_TRIAL_USD)) - est;
  for (const n of cell.nums) {
    const r = runs.find((x) => x.trial === n) ?? { trial: n, status: "harness_error", error: out.error ?? "runner did not report this trial" };
    records.set(key(cell.config, cell.ticket, n), {
      ...r, config: cell.config, ticket: cell.ticket, topup: n > TRIALS,
      paths_opened: out.paths_opened || [], void: null, audited: false, grade: null, judge: null,
    });
  }
}

async function audit(recs, ph) {
  for (const r of recs) {
    const hit = (r.paths_opened || []).find((p) => FORBIDDEN.some((f) => p.includes(f)));
    if (hit) voidRecord(r, `runner reported opening ${hit}`);
  }
  await parallel(Object.entries(groupBy(recs, (r) => r.config)).map(([cfg, rs]) => async () => {
    try {
      const a = await agent(auditPrompt(cfg, rs, ph), { label: `${R} audit ${ph} ${cfg}`, phase: ph === "Trials" ? "Audit" : ph, schema: AUDIT_SCHEMA, model: AGENT_MODEL });
      for (const v of a.voided) { const r = records.get(key(cfg, v.ticket, v.trial)); if (r) voidRecord(r, v.evidence); }
      const missing = new Set(a.missing_traces);
      for (const r of rs) r.audited = r.status !== "completed" || (!!r.trace_path && !missing.has(r.trace_path));
      auditNotes.push(`${ph} ${cfg}: ${a.traces_scanned} traces, ${a.transcripts_scanned} transcripts, ${a.voided.length} voids, ${missing.size} missing traces. ${a.notes ?? ""}`);
    } catch (e) {
      auditNotes.push(`${ph} ${cfg}: audit agent failed (${e}). These trials are unaudited.`);
    }
  }));
}

async function grade(recs, ph) {
  let ok = true;
  const todo = recs.filter((r) => r.status === "completed" && !r.void);
  await parallel(Object.entries(groupBy(todo, (r) => r.config)).map(([cfg, rs]) => async () => {
    const input = `${RUN_DIR}/grade-input-${cfg}-${ph.toLowerCase()}.json`;
    const payload = JSON.stringify(rs.map((r) => ({ ticket: r.ticket, trial: r.trial, label: { category: r.category, priority: r.priority } })));
    try {
      const g = await agent(gradePrompt(input, payload), { label: `${R} grade ${ph} ${cfg}`, phase: ph === "Trials" ? "Grade" : ph, schema: GRADE_SCHEMA, model: AGENT_MODEL });
      if (!g.selftest_passed) { ok = false; gradeNotes.push(`${ph} ${cfg}: grader selftest failed. ${g.selftest_output ?? ""}`); return; }
      for (const x of g.results) {
        const r = records.get(key(cfg, x.ticket, x.trial));
        if (r) r.grade = { ...x, both_ok: x.category_ok && x.priority_ok };
      }
      const ungraded = rs.filter((r) => !r.grade).length;
      if (ungraded) { ok = false; gradeNotes.push(`${ph} ${cfg}: ${ungraded} records came back ungraded`); }
      if (g.errors?.length) gradeNotes.push(...g.errors.map((e) => `${ph} ${cfg}: ${e}`));
    } catch (e) {
      ok = false;
      gradeNotes.push(`${ph} ${cfg}: grader agent failed (${e})`);
    }
  }));
  return ok;
}

// ---------- metrics and report ----------
function metrics(recs, planned) {
  const done = recs.filter((r) => r.status === "completed" && !r.void);
  const graded = done.filter((r) => r.grade);
  const judged = done.filter((r) => r.judge);
  const calls = sum(done.map((r) => r.tool_calls));
  return {
    planned, completed: done.length,
    voided: recs.filter((r) => r.void).length,
    harness_errors: recs.filter((r) => r.status !== "completed").length,
    unaudited: done.filter((r) => !r.audited).length,
    category_acc: r3(rate(graded, (r) => r.grade.category_ok)), // grade.py label.category
    priority_acc: r3(rate(graded, (r) => r.grade.priority_ok)), // grade.py label.priority
    both_acc: r3(rate(graded, (r) => r.grade.both_ok)),
    tone_mean: r3(mean(judged.map((r) => r.judge.tone))),       // judge.md
    tone_pass_rate: r3(rate(judged, (r) => r.judge.pass)),
    runtime_ms_mean: r3(mean(done.map((r) => r.runtime_ms).filter((x) => x != null))),
    tool_calls_mean: r3(mean(done.map((r) => r.tool_calls).filter((x) => x != null))),
    tool_error_rate: calls ? r3(sum(done.map((r) => r.tool_errors)) / calls) : null,
    tokens_mean: r3(mean(done.map((r) => (r.input_tokens || 0) + (r.output_tokens || 0)))),
    cost_usd: r3(sum(done.map((r) => r.cost_usd))),
  };
}

function byConfig(pred, plannedPerConfig) {
  return Object.fromEntries(CONFIG_IDS.map((c) => [c, metrics(all().filter((r) => r.config === c && pred(r)), plannedPerConfig)]));
}

function report(halted, extra = {}) {
  const ticketsInRun = new Set(cells.map((c) => c.ticket)).size;
  return {
    round: ROUND, label: R, configs: CONFIGS, dry_run: !!ONLY, halted,
    budget_cap_hit: skipped.length > 0,
    primary: byConfig((r) => !r.topup, ticketsInRun * TRIALS),
    topup: byConfig((r) => r.topup, null),
    combined: byConfig(() => true, null),
    spend: { est_spent_usd: r3(spentUsd), cap_usd: CAP_USD, skipped },
    voids, audit_notes: auditNotes, grade_notes: gradeNotes, judge_notes: judgeNotes,
    judge_family_note: "The Opus judge is in the same model family as the Sonnet agent under test. No judge from another family was available, so the two may share blind spots.",
    records: all().map(({ reply, paths_opened, ...rest }) => rest),
    ...extra,
  };
}

// ---------- run ----------
for (const c of CONFIG_IDS) if (!CONFIGS[c]) throw new Error(`Unknown config ${c}. Halting before any spend.`);
if (!ONLY && TICKETS.length !== EXPECTED_TICKETS) throw new Error(`${R}: expected ${EXPECTED_TICKETS} tickets, got ${TICKETS.length}. Halting before any spend.`);

let cells = [];
for (const config of CONFIG_IDS) for (const ticket of TICKETS) cells.push({ config, ticket, nums: range(1, TRIALS) });
if (ONLY) cells = cells.filter((c) => ONLY.includes(`${c.config}:${c.ticket}`));
log(`${R}: ${cells.length} cells x ${TRIALS} trials. Cap $${CAP_USD}. Trial estimate ~$${(cells.length * TRIALS * EST_TRIAL_USD).toFixed(2)} (unmeasured until the dry run).`);

phase("Trials");
await inWaves(cells, (c) => runCell(c, "Trials"));

phase("Audit");
const primaryRecs = all().filter((r) => !r.topup);
await audit(primaryRecs, "Trials");
const voidFrac = primaryRecs.length ? primaryRecs.filter((r) => r.void).length / primaryRecs.length : 0;
if (voidFrac > MAX_VOID_FRAC) return report(`answer key leak: ${(voidFrac * 100).toFixed(1)}% of trials peeked`);

phase("Grade");
if (!(await grade(primaryRecs, "Trials"))) return report("broken grader or ungraded records");

phase("Top-up");
const split = [];
for (const rs of Object.values(groupBy(primaryRecs.filter((r) => r.grade), (r) => `${r.config}:${r.ticket}`))) {
  const pass = rs.filter((r) => r.grade.both_ok).length;
  if (pass > 0 && pass < rs.length) split.push({ config: rs[0].config, ticket: rs[0].ticket, frac: pass / rs.length });
}
split.sort((a, b) => Math.abs(a.frac - 0.5) - Math.abs(b.frac - 0.5));
const topupCells = TOPUP_PER_CELL > 0 ? split.slice(0, TOPUP_MAX_CELLS) : [];
for (const c of split.slice(topupCells.length)) skipped.push({ what: `Top-up ${c.config}:${c.ticket}`, reason: `top-up cell cap of ${TOPUP_MAX_CELLS}` });
log(`${split.length} split cells. ${topupCells.length} get ${TOPUP_PER_CELL} extra trials.`);
await inWaves(topupCells.map((c) => ({ config: c.config, ticket: c.ticket, nums: range(TRIALS + 1, TRIALS + TOPUP_PER_CELL) })), (c) => runCell(c, "Top-up"));
const topRecs = all().filter((r) => r.topup);
if (topRecs.length) {
  await audit(topRecs, "Top-up");
  if (!(await grade(topRecs, "Top-up"))) return report("broken grader during top-up");
}

phase("Judge");
const judgeable = all().filter((r) => !r.topup && r.status === "completed" && !r.void && r.reply);
await inWaves(Object.entries(groupBy(judgeable, (r) => r.ticket)), async ([ticket, rs]) => {
  if (!reserve(JUDGE_CALL_USD, `judge ${ticket}`)) return;
  const rnd = seeded(`${R}:${ticket}`);
  const items = rs.map((r) => ({ r, s: rnd() })).sort((a, b) => a.s - b.s).map((x, i) => ({ id: `R${i + 1}`, r: x.r }));
  try {
    const j = await agent(judgePrompt(ticket, items), { label: `${R} judge ${ticket}`, phase: "Judge", schema: JUDGE_SCHEMA, model: JUDGE_MODEL });
    const byId = Object.fromEntries(items.map((x) => [x.id, x.r]));
    for (const s of j.scores) if (byId[s.reply_id]) byId[s.reply_id].judge = s;
    const unscored = items.filter((x) => !x.r.judge).length;
    if (unscored) judgeNotes.push(`judge ${ticket}: ${unscored} replies unscored`);
  } catch (e) {
    judgeNotes.push(`judge ${ticket} failed: ${e}`);
  }
});

phase("Synthesis");
const failures = all()
  .filter((r) => r.status === "completed" && !r.void && ((r.grade && !r.grade.both_ok) || (r.judge && !r.judge.pass)))
  .map((r) => ({
    config: r.config, ticket: r.ticket, trial: r.trial,
    got: { category: r.category, priority: r.priority },
    expected: { category: r.grade?.expected_category, priority: r.grade?.expected_priority },
    tone: r.judge?.tone, tone_pass: r.judge?.pass, judge_note: r.judge?.note,
    tool_errors: r.tool_errors, reply_start: (r.reply || "").slice(0, 300),
  }));

let failureAnalysis = null;
try {
  failureAnalysis = await agent([
    `You analyze failed trials from an eval of the triage agent. Configs: ${JSON.stringify(CONFIGS)}.`,
    "Read spe/failures.md for the existing F-numbered failure types. Do not read spe/predictions/. The comparison with predictions happens at close-out.",
    "Group the failures below into failure types. Reuse an existing F-number when the type matches, and put it in existing_id. For each type give the name, the kind (agent, prompt, tool, grader, or harness), the configs and tickets, the count, What, How to spot it, and a proposed fix. If a failure looks like a grader or reference-label error, say so.",
    "Then list concrete proposals for the next round.",
    JSON.stringify(failures),
  ].join("\n\n"), { label: `${R} failure analysis`, phase: "Synthesis", schema: FAILURE_SCHEMA, model: AGENT_MODEL });
} catch (e) {
  failureAnalysis = { error: String(e) };
}

const draft = report(null, { failure_analysis: failureAnalysis });
let critic = null;
try {
  const { records: _omit, ...summary } = draft;
  critic = await agent([
    "You are a completeness critic for an eval run. You check the run summary below and list gaps. You change nothing.",
    `Check these points. Every planned cell (${cells.length} cells x ${TRIALS} trials) either ran or appears in spend.skipped. Completed, voided, and harness-error counts add up to the planned count. The grader selftest passed for every grading call. Harness errors and rate limits are not counted as model failures. Every completed, unvoided primary trial has a judge score. Unaudited trials are flagged. Top-up results are kept apart from the primary numbers. Spend stayed under the cap. All labels use ${R}.`,
    JSON.stringify(summary),
  ].join("\n\n"), { label: `${R} completeness critic`, phase: "Synthesis", schema: CRITIC_SCHEMA, model: AGENT_MODEL });
} catch (e) {
  critic = { complete: false, gaps: [`critic failed: ${e}`] };
}

return { ...draft, critic };
